@Repository
public class LogRepository {

    @PersistenceContext
    private EntityManager entityManager;

    public List<LogEntity> findNextPage(Instant lastCreatedAt, Long lastId, int limit) {
        // Keyset pagination implementation using JPA Criteria API
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();
        CriteriaQuery<LogEntity> query = cb.createQuery(LogEntity.class);
        Root<LogEntity> root = query.from(LogEntity.class);

        Predicate paginationPredicate;
        if (lastCreatedAt != null && lastId != null) {
            Predicate chronologicalCheck = cb.lessThan(root.get("createdAt"), lastCreatedAt);
            Predicate idTieBreaker = cb.and(
                cb.equal(root.get("createdAt"), lastCreatedAt),
                cb.lessThan(root.get("id"), lastId)
            );
            paginationPredicate = cb.or(chronologicalCheck, idTieBreaker);
        } else {
            paginationPredicate = cb.conjunction(); // First page
        }

        query.select(root)
             .where(paginationPredicate)
             .orderBy(cb.desc(root.get("createdAt")), cb.desc(root.get("id")));

        return entityManager.createQuery(query)
                .setMaxResults(limit)
                .getResultList();
    }
}
